package com.ruoyi.custom.availability;

import com.alibaba.fastjson2.*;
import com.ruoyi.common.core.redis.RedisCache;
import com.ruoyi.custom.domain.CustomDevice;
import com.ruoyi.custom.mapper.CustomDeviceMapper;
import com.ruoyi.wvp.media.bean.MediaServer;
import com.ruoyi.wvp.media.service.IMediaServerService;
import org.junit.*;
import org.springframework.data.redis.core.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CustomAvailabilityEvidenceTest {
    static class Memory extends RedisCache {
        final Map<String,String> data=new ConcurrentHashMap<>();
        @Override @SuppressWarnings("unchecked") public <T>T getCacheObject(String key){return (T)data.get(key);}
        @Override public <T>void setCacheObject(String key,T value,Integer timeout,TimeUnit unit){data.put(key,(String)value);}
        @Override public boolean deleteObject(String key){return data.remove(key)!=null;}
    }
    static CustomDevice device(long id,String url){CustomDevice d=new CustomDevice();d.setId(id);d.setStreamUrl(url);return d;}
    static CustomStreamProbe.Result result(String reason){return new CustomStreamProbe.Result(reason,"CUSTOM_STREAM_PROBE",false);}
    Memory redis;CustomAvailabilityCache cache;CustomStreamSpec source;
    @Before public void setup(){redis=new Memory();cache=new CustomAvailabilityCache(redis,"default",30,3,2);source=new CustomStreamSpec(device(1,"rtsp://user:password@192.168.1.20/video"));}
    @Test public void failureAndRecoveryThresholdsAndDistinctErrors(){assertEquals("UNKNOWN",cache.record(source,result("UNREACHABLE")).getSnapshot().getState());cache.record(source,result("UNREACHABLE"));assertEquals("OFFLINE",cache.record(source,result("UNREACHABLE")).getSnapshot().getState());assertEquals("UNKNOWN",cache.record(source,result("AVAILABLE")).getSnapshot().getState());assertEquals("ONLINE",cache.record(source,result("AVAILABLE")).getSnapshot().getState());cache.record(source,result("AUTHENTICATION_FAILED"));cache.record(source,result("AUTHENTICATION_FAILED"));assertEquals("AUTH_ERROR",cache.record(source,result("AUTHENTICATION_FAILED")).getSnapshot().getState());cache.record(source,result("STREAM_TIMEOUT"));assertEquals("STREAM_ERROR",cache.get(source).getSnapshot().getState());}
    @Test public void staleAndFutureEvidenceIsUnknownAndRecoveryRestarts(){cache.record(source,result("AVAILABLE"));CustomAvailabilityCache.Evidence e=cache.record(source,result("AVAILABLE"));e.getSnapshot().setLastAvailableAt(System.currentTimeMillis()-31000);e.getSnapshot().setCheckedAt(System.currentTimeMillis());redis.data.put(cache.key(source),JSON.toJSONString(e));assertEquals("UNKNOWN",cache.get(source).getSnapshot().getState());assertEquals("UNKNOWN",cache.record(source,result("AVAILABLE")).getSnapshot().getState());assertEquals("ONLINE",cache.record(source,result("AVAILABLE")).getSnapshot().getState());e=cache.get(source);e.getSnapshot().setLastAvailableAt(System.currentTimeMillis()+10000);redis.data.put(cache.key(source),JSON.toJSONString(e));assertEquals("UNKNOWN",cache.get(source).getSnapshot().getState());}
    @Test public void offlineAlsoExpiresAndUnknownFormatsDoNotBecomeOffline(){CustomAvailabilityCache.Evidence e=null;for(int i=0;i<3;i++)e=cache.record(source,result("UNREACHABLE"));e.getSnapshot().setCheckedAt(System.currentTimeMillis()-31000);redis.data.put(cache.key(source),JSON.toJSONString(e));assertEquals("UNKNOWN",cache.get(source).getSnapshot().getState());for(String reason:Arrays.asList("UNSUPPORTED_CONTENT","AUTHENTICATION_UNSUPPORTED","UNSUPPORTED_SIGNAL_ONLY","TLS_VALIDATION_FAILED","ADDRESS_BLOCKED")){for(int i=0;i<3;i++)cache.record(source,result(reason));assertEquals(reason,"UNKNOWN",cache.get(source).getSnapshot().getState());}}
    @Test public void trueFrameGrowthCanRecoverImmediately(){CustomAvailabilityCache.Evidence e=cache.record(source,new CustomStreamProbe.Result("AVAILABLE","CUSTOM_MEDIA_RECEIVING",true));assertEquals("ONLINE",e.getSnapshot().getState());assertEquals("CUSTOM_MEDIA_RECEIVING",e.getSource());assertTrue(e.getSnapshot().getLastAvailableAt()>0);}
    @Test public void addressPasswordTimeAndGatewayChangesCannotReuseEvidence(){cache.record(source,new CustomStreamProbe.Result("AVAILABLE","CUSTOM_MEDIA_RECEIVING",true));assertEquals("UNKNOWN",cache.get(new CustomStreamSpec(device(1,"rtsp://user:other@192.168.1.20/video"))).getSnapshot().getState());CustomDevice revised=device(1,source.device.getStreamUrl());revised.setUpdateTime(new Date());assertEquals("UNKNOWN",cache.get(new CustomStreamSpec(revised)).getSnapshot().getState());assertEquals("UNKNOWN",new CustomAvailabilityCache(redis,"default","different","",30,3,2).get(source).getSnapshot().getState());assertEquals("UNKNOWN",new CustomAvailabilityCache(redis,"foreign",30,3,2).get(source).getSnapshot().getState());assertFalse(cache.key(source).contains("password"));}
    @Test public void leaseHasOwnershipAndBoundedExpiry(){redis.redisTemplate=mock(RedisTemplate.class);ValueOperations values=mock(ValueOperations.class);when(redis.redisTemplate.opsForValue()).thenReturn(values);when(values.setIfAbsent(anyString(),anyString(),eq(20L),eq(TimeUnit.SECONDS))).thenReturn(true,false);String owner=cache.claim(source);assertNotNull(owner);assertNull(cache.claim(source));cache.release(source,owner);verify(redis.redisTemplate).execute(any(org.springframework.data.redis.core.script.DefaultRedisScript.class),eq(Collections.singletonList(cache.key(source)+":probe")),eq(owner));cache.release(source,null);verify(values,times(2)).setIfAbsent(anyString(),anyString(),eq(20L),eq(TimeUnit.SECONDS));}
    @Test public void bindingsNeverBorrowOtherProtocolAndExpireOnRevision(){CustomMediaBindings b=new CustomMediaBindings();assertThrows(IllegalArgumentException.class,()->b.add(source,"srv","rtsp_preview","x",0));b.add(source,"srv","custom_preview","x",System.currentTimeMillis()+10000);assertEquals(1,b.matching(source).size());assertEquals(0,b.matching(new CustomStreamSpec(device(1,"rtsp://different/video"))).size());b.renew("custom_preview","x",System.currentTimeMillis()-1);assertTrue(b.matching(source).isEmpty());b.add(source,"srv","custom","x",0);b.remove("custom","x");assertTrue(b.matching(source).isEmpty());assertTrue(b.consumeChanged().contains(1L));assertTrue(b.consumeChanged().isEmpty());}
    static JSONObject sample(long frames,boolean video){return JSON.parseObject("{\"code\":0,\"tracks\":[{\"codec_type\":"+(video?0:1)+",\"ready\":true,\"frames\":"+frames+"}]}");}
    @Test public void mediaRequiresIncreasingVideoFramesAndMatchingOrigin(){IMediaServerService media=mock(IMediaServerService.class);MediaServer srv=mock(MediaServer.class);when(media.getOne("srv")).thenReturn(srv);when(srv.isStatus()).thenReturn(true);CustomMediaBindings.Binding b=new CustomMediaBindings.Binding(1L,source.fingerprint,"srv","custom_preview","x",0);AtomicInteger calls=new AtomicInteger();CustomMediaPacketReader reader=new CustomMediaPacketReader(media){@Override protected JSONObject sample(MediaServer s,CustomMediaBindings.Binding ignored,long deadline){return CustomAvailabilityEvidenceTest.sample(10+calls.getAndIncrement(),true);}};assertTrue(reader.receiving(b,ProtocolFixture.deadline(1000)));b.originHash=CustomMediaBindings.addressHash("other");assertFalse(reader.receiving(b,ProtocolFixture.deadline(1000)));assertEquals(-1,CustomMediaPacketReader.videoFrames(sample(100,true).fluentPut("code",1)));assertEquals(-1,CustomMediaPacketReader.videoFrames(sample(100,false)));}
    @Test public void oldReadyTrackDoesNotBecomeReceiving(){IMediaServerService media=mock(IMediaServerService.class);MediaServer srv=mock(MediaServer.class);when(media.getOne("srv")).thenReturn(srv);when(srv.isStatus()).thenReturn(true);CustomMediaPacketReader reader=new CustomMediaPacketReader(media){@Override protected JSONObject sample(MediaServer s,CustomMediaBindings.Binding b,long deadline){return CustomAvailabilityEvidenceTest.sample(100,true);}};assertFalse(reader.receiving(new CustomMediaBindings.Binding(1L,source.fingerprint,"srv","custom","x",0),ProtocolFixture.deadline(1000)));}
    @Test public void deniedAddressesAndMalformedCidrsCannotResolveOrProbe()throws Exception{CustomStreamAddressPolicy p=new CustomStreamAddressPolicy("10.0.0.0/8");try{for(String address:Arrays.asList("127.0.0.1","0.0.0.0","169.254.169.254","100.100.100.200","168.63.129.16","224.0.0.1","::1","fe80::1","fd00:ec2::254","192.168.33.5"))assertFalse(address,p.allowed(InetAddress.getByName(address)));assertTrue(p.allowed(InetAddress.getByName("10.111.222.30")));assertTrue(p.allowed(InetAddress.getByName("8.8.8.8")));}finally{p.close();}assertThrows(IllegalArgumentException.class,()->new CustomStreamAddressPolicy("arbitrary-host.invalid/32"));assertFalse(CustomStreamAddressPolicy.inNetwork(InetAddress.getLoopbackAddress(),"host.invalid/8"));}
    @Test public void mixedDnsAndSlowDnsAreBounded()throws Exception{CustomStreamAddressPolicy p=new CustomStreamAddressPolicy(""){@Override protected InetAddress[] resolve(String h)throws Exception{return new InetAddress[]{InetAddress.getByName("8.8.8.8"),InetAddress.getLoopbackAddress()};}};try{assertEquals("ADDRESS_BLOCKED",assertThrows(CustomStreamSpec.ProbeFailure.class,()->p.pin(URI.create("http://fixture.invalid"),ProtocolFixture.deadline(500))).reason);}finally{p.close();}CustomStreamAddressPolicy slow=new CustomStreamAddressPolicy(""){@Override protected InetAddress[] resolve(String h)throws Exception{Thread.sleep(2000);return new InetAddress[]{InetAddress.getByName("8.8.8.8")};}};try{long now=System.nanoTime();assertThrows(CustomStreamSpec.ProbeFailure.class,()->slow.pin(URI.create("http://fixture.invalid"),ProtocolFixture.deadline(100)));assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-now)<500);}finally{slow.close();}}
    @Test public void monitorCapsWorkersDiscardsEditedResultsAndDoesNotPublishAfterClose()throws Exception{CustomDeviceMapper mapper=mock(CustomDeviceMapper.class);CustomAvailabilityCache memory=mock(CustomAvailabilityCache.class);CustomStreamProbe probe=mock(CustomStreamProbe.class);when(memory.get(any())).thenReturn(new CustomAvailabilityCache.Evidence());when(memory.claim(any())).thenReturn("owner");when(memory.record(any(),any())).thenReturn(new CustomAvailabilityCache.Evidence());when(probe.consumeMediaChanges()).thenReturn(Collections.emptySet());CountDownLatch entered=new CountDownLatch(2),release=new CountDownLatch(1);AtomicInteger active=new AtomicInteger(),max=new AtomicInteger();when(probe.check(any(),anyInt())).thenAnswer(call->{int n=active.incrementAndGet();max.accumulateAndGet(n,Math::max);entered.countDown();try{release.await();return result("AVAILABLE");}finally{active.decrementAndGet();}});List<CustomDevice> rows=Arrays.asList(device(1,"rtsp://192.168.1.20/a"),device(2,"rtsp://192.168.1.20/b"),device(3,"rtsp://192.168.1.20/c"));when(mapper.selectDeviceList(any())).thenReturn(rows);when(mapper.selectDeviceById(anyLong())).thenReturn(device(1,"rtsp://changed/a"));CustomAvailabilityMonitor monitor=new CustomAvailabilityMonitor(mapper,memory,probe,true,30,300,500);try{rows.forEach(monitor::invalidate);monitor.tick();assertTrue(entered.await(1,TimeUnit.SECONDS));assertEquals(2,max.get());monitor.close();release.countDown();Thread.sleep(100);verify(memory,never()).record(any(),any());monitor.tick();verify(probe,times(2)).check(any(),anyInt());verify(memory,times(2)).release(any(),eq("owner"));}finally{release.countDown();monitor.close();}}
    @Test public void monitorDiscardsLateConfigurationResult()throws Exception{CustomDeviceMapper mapper=mock(CustomDeviceMapper.class);CustomAvailabilityCache memory=mock(CustomAvailabilityCache.class);CustomStreamProbe probe=mock(CustomStreamProbe.class);when(memory.get(any())).thenReturn(new CustomAvailabilityCache.Evidence());when(memory.claim(any())).thenReturn("owner");when(probe.check(any(),anyInt())).thenReturn(result("AVAILABLE"));when(mapper.selectDeviceById(1L)).thenReturn(device(1,"rtsp://changed/video"));CustomAvailabilityMonitor monitor=new CustomAvailabilityMonitor(mapper,memory,probe,true,30,300,500);try{monitor.preflight(source.device);verify(memory,never()).record(any(),any());verify(memory).release(any(),eq("owner"));}finally{monitor.close();}}
    @Test public void editedSourcePreflightCannotReceiveOldRunningOnlineResult()throws Exception{
        CustomDeviceMapper mapper=mock(CustomDeviceMapper.class);CustomAvailabilityCache memory=mock(CustomAvailabilityCache.class);CustomStreamProbe probe=mock(CustomStreamProbe.class);
        CustomDevice next=device(1,"rtsp://changed/video");when(memory.get(any())).thenReturn(new CustomAvailabilityCache.Evidence());
        Future<CustomAvailabilityCache.Evidence> oldWork=mock(Future.class);when(oldWork.isDone()).thenReturn(false);CustomAvailabilityCache.Evidence old=new CustomAvailabilityCache.Evidence();old.getSnapshot().setState("ONLINE");when(oldWork.get(anyLong(),eq(TimeUnit.MILLISECONDS))).thenReturn(old);
        CustomAvailabilityMonitor monitor=new CustomAvailabilityMonitor(mapper,memory,probe,true,30,300,500);
        try{Map<Long,Future<CustomAvailabilityCache.Evidence>> running=(Map<Long,Future<CustomAvailabilityCache.Evidence>>)ReflectionTestUtils.getField(monitor,"running");running.put(1L,oldWork);
            assertEquals("UNKNOWN",monitor.preflight(next).getSnapshot().getState());verify(probe,never()).check(any(),anyInt());verify(memory,never()).record(any(),any());
        }finally{monitor.close();}
    }
    @Test public void backoffIsCappedAndPolicyConfigurationInvalidatesCache()throws Exception{CustomDeviceMapper mapper=mock(CustomDeviceMapper.class);CustomAvailabilityCache memory=mock(CustomAvailabilityCache.class);CustomStreamProbe probe=mock(CustomStreamProbe.class);when(memory.get(any())).thenReturn(new CustomAvailabilityCache.Evidence());when(memory.claim(any())).thenReturn("owner");CustomAvailabilityCache.Evidence failed=new CustomAvailabilityCache.Evidence();failed.getSnapshot().setFailureCount(100);when(memory.record(any(),any())).thenReturn(failed);when(probe.check(any(),anyInt())).thenReturn(result("UNREACHABLE"));when(mapper.selectDeviceById(1L)).thenReturn(source.device);CustomAvailabilityMonitor monitor=new CustomAvailabilityMonitor(mapper,memory,probe,true,30,300,500);try{long now=System.currentTimeMillis();monitor.preflight(source.device);Map<Long,Long> due=(Map<Long,Long>)ReflectionTestUtils.getField(monitor,"due");assertTrue(due.get(1L)-now>=300000);assertTrue(due.get(1L)-now<301000);}finally{monitor.close();}cache.record(source,new CustomStreamProbe.Result("AVAILABLE","CUSTOM_MEDIA_RECEIVING",true));assertEquals("UNKNOWN",new CustomAvailabilityCache(redis,"default","default","","10.0.0.0/8",30,3,2).get(source).getSnapshot().getState());}
    @Test public void customMapperLoggingNeverIncludesSourceParameters(){new CustomSourceLogProtection().protectSourceParameters();assertFalse(org.slf4j.LoggerFactory.getLogger("com.ruoyi.custom.mapper.CustomDeviceMapper").isDebugEnabled());assertFalse(org.slf4j.LoggerFactory.getLogger("com.ruoyi.custom.mapper.CustomDeviceMapper").isTraceEnabled());}
    @Test public void previewWaitTimeoutCancelsUnderlyingWork()throws Exception{
        CustomAvailabilityCache memory=mock(CustomAvailabilityCache.class);when(memory.get(any())).thenReturn(new CustomAvailabilityCache.Evidence());
        CustomAvailabilityMonitor monitor=new CustomAvailabilityMonitor(mock(CustomDeviceMapper.class),memory,mock(CustomStreamProbe.class),true,30,300,500);
        Future<CustomAvailabilityCache.Evidence> task=mock(Future.class);when(task.isDone()).thenReturn(false);when(task.get(anyLong(),eq(TimeUnit.MILLISECONDS))).thenThrow(new TimeoutException());
        try{Map<Long,Future<CustomAvailabilityCache.Evidence>> running=(Map<Long,Future<CustomAvailabilityCache.Evidence>>)ReflectionTestUtils.getField(monitor,"running");running.put(1L,task);assertEquals("UNKNOWN",monitor.preflight(source.device).getSnapshot().getState());verify(task).cancel(true);}finally{monitor.close();}
    }
}
